create table if not exists public.review_reports (id uuid primary key default gen_random_uuid(),review_id uuid not null references public.reviews(id) on delete cascade,reporter_id uuid not null references public.profiles(id),reason text not null,details text,created_at timestamptz not null default now(),status text not null default 'pending' check(status in ('pending','reviewing','resolved','dismissed')),resolved_by uuid references public.profiles(id),resolved_at timestamptz);
create unique index if not exists review_reports_reporter_review_unique on public.review_reports(reporter_id,review_id);
create index if not exists review_reports_status_created_idx on public.review_reports(status,created_at);
alter table public.review_reports enable row level security;
drop policy if exists review_reports_insert_own on public.review_reports;
create policy review_reports_insert_own on public.review_reports for insert to authenticated with check(reporter_id=auth.uid());
drop policy if exists review_reports_select_own_or_admin on public.review_reports;
create policy review_reports_select_own_or_admin on public.review_reports for select to authenticated using (reporter_id=auth.uid() or exists(select 1 from public.profiles p where p.id=auth.uid() and p.is_admin=true));
revoke update,delete on public.review_reports from authenticated;
revoke insert,update,delete on public.review_reports from anon;
create or replace function public.report_review(p_review_id uuid,p_reason text,p_details text default null) returns public.review_reports language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v public.review_reports%rowtype; begin if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if; if nullif(trim(p_reason),'') is null then raise exception 'REPORT_REASON_REQUIRED'; end if; if not exists(select 1 from public.reviews where id=p_review_id) then raise exception 'REVIEW_NOT_FOUND'; end if; insert into public.review_reports(review_id,reporter_id,reason,details) values(p_review_id,auth.uid(),trim(p_reason),nullif(trim(p_details),'')) returning * into v; return v; exception when unique_violation then raise exception 'REVIEW_ALREADY_REPORTED_BY_USER'; end; $function$;
create or replace function public.resolve_review_report(p_report_id uuid,p_status text,p_review_status public.review_status default null,p_reason text default null) returns jsonb language plpgsql security definer set search_path='public','auth','extensions','pg_temp' as $function$ declare v public.review_reports%rowtype; v_review public.reviews%rowtype; v_admin uuid:=auth.uid(); v_reason text:=nullif(trim(p_reason),''); begin if not exists(select 1 from public.profiles where id=v_admin and is_admin=true) then raise exception 'ADMIN_REQUIRED'; end if; if p_status not in ('resolved','dismissed') then raise exception 'INVALID_REPORT_STATUS'; end if; select * into v from public.review_reports where id=p_report_id for update; if not found then raise exception 'REPORT_NOT_FOUND'; end if; if p_review_status is not null then if p_review_status not in ('published','hidden') then raise exception 'INVALID_REVIEW_STATUS'; end if; perform public.moderate_review(v.review_id,p_review_status,coalesce(v_reason,'Resolved report')); end if; update public.review_reports set status=p_status,resolved_by=v_admin,resolved_at=now() where id=p_report_id returning * into v; select * into v_review from public.reviews where id=v.review_id; return jsonb_build_object('report',to_jsonb(v),'review',to_jsonb(v_review)); end; $function$;
comment on function public.report_review(uuid,text,text) is 'Authenticated users can report a review once; reports are immutable user submissions and are resolved only through moderation tooling.';
comment on function public.resolve_review_report(uuid,text,public.review_status,text) is 'Admin-only report resolution with optional canonical review moderation and provenance.';
